-- 同步主键 ID 自增序列
SELECT setval('users_id_seq', (SELECT COALESCE(MAX(id), 1) FROM users));
SELECT setval('classrooms_id_seq', (SELECT COALESCE(MAX(id), 1) FROM classrooms));
SELECT setval('sessions_id_seq', (SELECT COALESCE(MAX(id), 1) FROM sessions));
SELECT setval('analysis_results_id_seq', (SELECT COALESCE(MAX(id), 1) FROM analysis_results));